mkitem!{mktrait!{# [doc = " WASI-specific extensions to [`File`]."] pub trait FileExt { # [doc = " Reads a number of bytes starting from a given offset."] # [doc = ""] # [doc = " Returns the number of bytes read."] # [doc = ""] # [doc = " The offset is relative to the start of the file and thus independent"] # [doc = " from the current cursor."] # [doc = ""] # [doc = " The current file cursor is not affected by this function."] # [doc = ""] # [doc = " Note that similar to [`File::read`], it is not an error to return with a"] # [doc = " short read."] fn read_at (& self , buf : & mut [u8] , offset : u64) -> io :: Result < usize > { let bufs = & mut [IoSliceMut :: new (buf)] ; self . read_vectored_at (bufs , offset) } # [doc = " Reads a number of bytes starting from a given offset."] # [doc = ""] # [doc = " Returns the number of bytes read."] # [doc = ""] # [doc = " The offset is relative to the start of the file and thus independent"] # [doc = " from the current cursor."] # [doc = ""] # [doc = " The current file cursor is not affected by this function."] # [doc = ""] # [doc = " Note that similar to [`File::read_vectored`], it is not an error to"] # [doc = " return with a short read."] fn read_vectored_at (& self , bufs : & mut [IoSliceMut < '_ >] , offset : u64) -> io :: Result < usize > ; # [doc = " Reads the exact number of byte required to fill `buf` from the given offset."] # [doc = ""] # [doc = " The offset is relative to the start of the file and thus independent"] # [doc = " from the current cursor."] # [doc = ""] # [doc = " The current file cursor is not affected by this function."] # [doc = ""] # [doc = " Similar to [`Read::read_exact`] but uses [`read_at`] instead of `read`."] # [doc = ""] # [doc = " [`read_at`]: FileExt::read_at"] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " If this function encounters an error of the kind"] # [doc = " [`io::ErrorKind::Interrupted`] then the error is ignored and the operation"] # [doc = " will continue."] # [doc = ""] # [doc = " If this function encounters an \"end of file\" before completely filling"] # [doc = " the buffer, it returns an error of the kind [`io::ErrorKind::UnexpectedEof`]."] # [doc = " The contents of `buf` are unspecified in this case."] # [doc = ""] # [doc = " If any other read error is encountered then this function immediately"] # [doc = " returns. The contents of `buf` are unspecified in this case."] # [doc = ""] # [doc = " If this function returns an error, it is unspecified how many bytes it"] # [doc = " has read, but it will never read more than would be necessary to"] # [doc = " completely fill the buffer."] fn read_exact_at (& self , mut buf : & mut [u8] , mut offset : u64) -> io :: Result < () > { while ! buf . is_empty () { match self . read_at (buf , offset) { Ok (0) => break , Ok (n) => { let tmp = buf ; buf = & mut tmp [n ..] ; offset += n as u64 ; } Err (ref e) if e . is_interrupted () => { } Err (e) => return Err (e) , } } if ! buf . is_empty () { Err (io :: Error :: READ_EXACT_EOF) } else { Ok (()) } } # [doc = " Writes a number of bytes starting from a given offset."] # [doc = ""] # [doc = " Returns the number of bytes written."] # [doc = ""] # [doc = " The offset is relative to the start of the file and thus independent"] # [doc = " from the current cursor."] # [doc = ""] # [doc = " The current file cursor is not affected by this function."] # [doc = ""] # [doc = " When writing beyond the end of the file, the file is appropriately"] # [doc = " extended and the intermediate bytes are initialized with the value 0."] # [doc = ""] # [doc = " Note that similar to [`File::write`], it is not an error to return a"] # [doc = " short write."] fn write_at (& self , buf : & [u8] , offset : u64) -> io :: Result < usize > { let bufs = & [IoSlice :: new (buf)] ; self . write_vectored_at (bufs , offset) } # [doc = " Writes a number of bytes starting from a given offset."] # [doc = ""] # [doc = " Returns the number of bytes written."] # [doc = ""] # [doc = " The offset is relative to the start of the file and thus independent"] # [doc = " from the current cursor."] # [doc = ""] # [doc = " The current file cursor is not affected by this function."] # [doc = ""] # [doc = " When writing beyond the end of the file, the file is appropriately"] # [doc = " extended and the intermediate bytes are initialized with the value 0."] # [doc = ""] # [doc = " Note that similar to [`File::write_vectored`], it is not an error to return a"] # [doc = " short write."] fn write_vectored_at (& self , bufs : & [IoSlice < '_ >] , offset : u64) -> io :: Result < usize > ; # [doc = " Attempts to write an entire buffer starting from a given offset."] # [doc = ""] # [doc = " The offset is relative to the start of the file and thus independent"] # [doc = " from the current cursor."] # [doc = ""] # [doc = " The current file cursor is not affected by this function."] # [doc = ""] # [doc = " This method will continuously call [`write_at`] until there is no more data"] # [doc = " to be written or an error of non-[`io::ErrorKind::Interrupted`] kind is"] # [doc = " returned. This method will not return until the entire buffer has been"] # [doc = " successfully written or such an error occurs. The first error that is"] # [doc = " not of [`io::ErrorKind::Interrupted`] kind generated from this method will be"] # [doc = " returned."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This function will return the first error of"] # [doc = " non-[`io::ErrorKind::Interrupted`] kind that [`write_at`] returns."] # [doc = ""] # [doc = " [`write_at`]: FileExt::write_at"] fn write_all_at (& self , mut buf : & [u8] , mut offset : u64) -> io :: Result < () > { while ! buf . is_empty () { match self . write_at (buf , offset) { Ok (0) => { return Err (io :: Error :: WRITE_ALL_EOF) ; } Ok (n) => { buf = & buf [n ..] ; offset += n as u64 } Err (ref e) if e . is_interrupted () => { } Err (e) => return Err (e) , } } Ok (()) } # [doc = " Adjusts the flags associated with this file."] # [doc = ""] # [doc = " This corresponds to the `fd_fdstat_set_flags` syscall."] # [doc (alias = "fd_fdstat_set_flags")] fn fdstat_set_flags (& self , flags : u16) -> io :: Result < () > ; # [doc = " Adjusts the rights associated with this file."] # [doc = ""] # [doc = " This corresponds to the `fd_fdstat_set_rights` syscall."] # [doc (alias = "fd_fdstat_set_rights")] fn fdstat_set_rights (& self , rights : u64 , inheriting : u64) -> io :: Result < () > ; # [doc = " Provides file advisory information on a file descriptor."] # [doc = ""] # [doc = " This corresponds to the `fd_advise` syscall."] # [doc (alias = "fd_advise")] fn advise (& self , offset : u64 , len : u64 , advice : u8) -> io :: Result < () > ; # [doc = " Forces the allocation of space in a file."] # [doc = ""] # [doc = " This corresponds to the `fd_allocate` syscall."] # [doc (alias = "fd_allocate")] fn allocate (& self , offset : u64 , len : u64) -> io :: Result < () > ; # [doc = " Creates a directory."] # [doc = ""] # [doc = " This corresponds to the `path_create_directory` syscall."] # [doc (alias = "path_create_directory")] fn create_directory < P : AsRef < Path > > (& self , dir : P) -> io :: Result < () > ; # [doc = " Reads the contents of a symbolic link."] # [doc = ""] # [doc = " This corresponds to the `path_readlink` syscall."] # [doc (alias = "path_readlink")] fn read_link < P : AsRef < Path > > (& self , path : P) -> io :: Result < PathBuf > ; # [doc = " Returns the attributes of a file or directory."] # [doc = ""] # [doc = " This corresponds to the `path_filestat_get` syscall."] # [doc (alias = "path_filestat_get")] fn metadata_at < P : AsRef < Path > > (& self , lookup_flags : u32 , path : P) -> io :: Result < Metadata > ; # [doc = " Unlinks a file."] # [doc = ""] # [doc = " This corresponds to the `path_unlink_file` syscall."] # [doc (alias = "path_unlink_file")] fn remove_file < P : AsRef < Path > > (& self , path : P) -> io :: Result < () > ; # [doc = " Removes a directory."] # [doc = ""] # [doc = " This corresponds to the `path_remove_directory` syscall."] # [doc (alias = "path_remove_directory")] fn remove_directory < P : AsRef < Path > > (& self , path : P) -> io :: Result < () > ; }}}
mkitem!{mkimpl!{impl FileExt for fs :: File { fn read_vectored_at (& self , bufs : & mut [IoSliceMut < '_ >] , offset : u64) -> io :: Result < usize > { self . as_inner () . as_inner () . pread (bufs , offset) } fn write_vectored_at (& self , bufs : & [IoSlice < '_ >] , offset : u64) -> io :: Result < usize > { self . as_inner () . as_inner () . pwrite (bufs , offset) } fn fdstat_set_flags (& self , flags : u16) -> io :: Result < () > { self . as_inner () . as_inner () . set_flags (flags) } fn fdstat_set_rights (& self , rights : u64 , inheriting : u64) -> io :: Result < () > { self . as_inner () . as_inner () . set_rights (rights , inheriting) } fn advise (& self , offset : u64 , len : u64 , advice : u8) -> io :: Result < () > { let advice = match advice { a if a == wasi :: ADVICE_NORMAL . raw () => wasi :: ADVICE_NORMAL , a if a == wasi :: ADVICE_SEQUENTIAL . raw () => wasi :: ADVICE_SEQUENTIAL , a if a == wasi :: ADVICE_RANDOM . raw () => wasi :: ADVICE_RANDOM , a if a == wasi :: ADVICE_WILLNEED . raw () => wasi :: ADVICE_WILLNEED , a if a == wasi :: ADVICE_DONTNEED . raw () => wasi :: ADVICE_DONTNEED , a if a == wasi :: ADVICE_NOREUSE . raw () => wasi :: ADVICE_NOREUSE , _ => { return Err (io :: const_error ! (io :: ErrorKind :: InvalidInput , "invalid parameter 'advice'" ,)) ; } } ; self . as_inner () . as_inner () . advise (offset , len , advice) } fn allocate (& self , offset : u64 , len : u64) -> io :: Result < () > { self . as_inner () . as_inner () . allocate (offset , len) } fn create_directory < P : AsRef < Path > > (& self , dir : P) -> io :: Result < () > { self . as_inner () . as_inner () . create_directory (osstr2str (dir . as_ref () . as_ref ()) ?) } fn read_link < P : AsRef < Path > > (& self , path : P) -> io :: Result < PathBuf > { self . as_inner () . read_link (path . as_ref ()) } fn metadata_at < P : AsRef < Path > > (& self , lookup_flags : u32 , path : P) -> io :: Result < Metadata > { let m = self . as_inner () . metadata_at (lookup_flags , path . as_ref ()) ? ; Ok (FromInner :: from_inner (m)) } fn remove_file < P : AsRef < Path > > (& self , path : P) -> io :: Result < () > { self . as_inner () . as_inner () . unlink_file (osstr2str (path . as_ref () . as_ref ()) ?) } fn remove_directory < P : AsRef < Path > > (& self , path : P) -> io :: Result < () > { self . as_inner () . as_inner () . remove_directory (osstr2str (path . as_ref () . as_ref ()) ?) } }}}
mkitem!{mktrait!{# [doc = " WASI-specific extensions to [`fs::OpenOptions`]."] pub trait OpenOptionsExt { # [doc = " Pass custom `dirflags` argument to `path_open`."] # [doc = ""] # [doc = " This option configures the `dirflags` argument to the"] # [doc = " `path_open` syscall which `OpenOptions` will eventually call. The"] # [doc = " `dirflags` argument configures how the file is looked up, currently"] # [doc = " primarily affecting whether symlinks are followed or not."] # [doc = ""] # [doc = " By default this value is `__WASI_LOOKUP_SYMLINK_FOLLOW`, or symlinks are"] # [doc = " followed. You can call this method with 0 to disable following symlinks"] fn lookup_flags (& mut self , flags : u32) -> & mut Self ; # [doc = " Indicates whether `OpenOptions` must open a directory or not."] # [doc = ""] # [doc = " This method will configure whether the `__WASI_O_DIRECTORY` flag is"] # [doc = " passed when opening a file. When passed it will require that the opened"] # [doc = " path is a directory."] # [doc = ""] # [doc = " This option is by default `false`"] fn directory (& mut self , dir : bool) -> & mut Self ; # [doc = " Indicates whether `__WASI_FDFLAG_DSYNC` is passed in the `fs_flags`"] # [doc = " field of `path_open`."] # [doc = ""] # [doc = " This option is by default `false`"] fn dsync (& mut self , dsync : bool) -> & mut Self ; # [doc = " Indicates whether `__WASI_FDFLAG_NONBLOCK` is passed in the `fs_flags`"] # [doc = " field of `path_open`."] # [doc = ""] # [doc = " This option is by default `false`"] fn nonblock (& mut self , nonblock : bool) -> & mut Self ; # [doc = " Indicates whether `__WASI_FDFLAG_RSYNC` is passed in the `fs_flags`"] # [doc = " field of `path_open`."] # [doc = ""] # [doc = " This option is by default `false`"] fn rsync (& mut self , rsync : bool) -> & mut Self ; # [doc = " Indicates whether `__WASI_FDFLAG_SYNC` is passed in the `fs_flags`"] # [doc = " field of `path_open`."] # [doc = ""] # [doc = " This option is by default `false`"] fn sync (& mut self , sync : bool) -> & mut Self ; # [doc = " Indicates the value that should be passed in for the `fs_rights_base`"] # [doc = " parameter of `path_open`."] # [doc = ""] # [doc = " This option defaults based on the `read` and `write` configuration of"] # [doc = " this `OpenOptions` builder. If this method is called, however, the"] # [doc = " exact mask passed in will be used instead."] fn fs_rights_base (& mut self , rights : u64) -> & mut Self ; # [doc = " Indicates the value that should be passed in for the"] # [doc = " `fs_rights_inheriting` parameter of `path_open`."] # [doc = ""] # [doc = " The default for this option is the same value as what will be passed"] # [doc = " for the `fs_rights_base` parameter but if this method is called then"] # [doc = " the specified value will be used instead."] fn fs_rights_inheriting (& mut self , rights : u64) -> & mut Self ; # [doc = " Open a file or directory."] # [doc = ""] # [doc = " This corresponds to the `path_open` syscall."] # [doc (alias = "path_open")] fn open_at < P : AsRef < Path > > (& self , file : & File , path : P) -> io :: Result < File > ; }}}
